<!-- Section 5: Corporate Operational Directives Banner -->
<div class="grid grid-cols-1 md:grid-cols-3 gap-space-md pt-space-xs">
    <div class="bg-white p-space-md border-l-4 border-error shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-accent text-[22px] shrink-0 mt-0.5">shield_lock</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                Account Security &amp; Password Policy
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                New supplier portal accounts receive a one-time activation link valid for 72 hours. Credentials must not
                be shared across multiple personnel.
            </p>
        </div>
    </div>
    <div class="bg-white p-space-md border-l-4 border-secondary shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-secondary text-[22px] shrink-0 mt-0.5">admin_panel_settings</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                Role-Based Access Control (RBAC)
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                Assign minimum required privileges per function: PO acknowledgment (Sales), ASN dispatch (Logistics), or
                CAR response (Quality Assurance).
            </p>
        </div>
    </div>
    <div class="bg-white p-space-md border-l-4 border-primary shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-primary text-[22px] shrink-0 mt-0.5">history</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                90-Day Inactivity &amp; Audit Trail
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                Accounts inactive for over 90 days are automatically flagged for suspension. All portal sign-ins and
                electronic signatures are audit-logged.
            </p>
        </div>
    </div>
</div>
